<script>
const dom = {
root: document.getElementById('app-root'),
messages: document.getElementById('chat-messages'),
input: document.getElementById('chat-input'),
sendBtn: document.getElementById('send-btn'),
sidebar: document.getElementById('sidebar-panel'),
overlay: document.getElementById('sidebar-overlay'),
history: document.getElementById('history-container'),
attachmentTrigger: document.getElementById('attachment-trigger'),
attachmentMenu: document.getElementById('attachment-menu'),
fileChips: document.getElementById('file-chips'),
searchToggleUi: document.getElementById('search-toggle-ui'),
searchToggleKnob: document.getElementById('search-toggle-knob'),
imgInput: document.getElementById('hidden-image-input'),
fileInput: document.getElementById('hidden-file-input'),
menuToggleBtn: document.getElementById('menu-toggle-btn'),
newChatBtn: document.getElementById('new-chat-btn'),
toggleSearchBtn: document.getElementById('toggle-search-btn'),
uploadImageBtn: document.getElementById('upload-image-btn'),
uploadFileBtn: document.getElementById('upload-file-btn'),
inputContainerWrapper: document.getElementById('input-container-wrapper')
};

function loadHistoryFromStorage() {
try {
var raw = localStorage.getItem('chat_history');
if (!raw) return [];
var parsed = JSON.parse(raw);
if (Array.isArray(parsed)) return parsed;
return [];
} catch (e) {
return [];
}
}

var idCounter = 0;
function generateId() {
idCounter++;
return 'id-' + Date.now().toString(36) + '-' + idCounter.toString(36) + '-' + Math.random().toString(36).substring(2, 10);
}

var state = {
currentThread: [],
history: loadHistoryFromStorage(),
isSidebarOpen: false,
isAttachmentMenuOpen: false,
isSearchEnabled: false,
selectedFiles: [],
isGenerating: false,
codeWidgetStates: {},
generationAbortController: null,
userScrolledUp: false,
responseIndex: 0
};

function saveHistoryToStorage() {
try {
var json = JSON.stringify(state.history);
if (json.length > 4 * 1024 * 1024) {
while (state.history.length > 1 && JSON.stringify(state.history).length > 4 * 1024 * 1024) {
state.history.shift();
}
json = JSON.stringify(state.history);
}
localStorage.setItem('chat_history', json);
} catch (e) {
if (state.history.length > 1) {
state.history.shift();
saveHistoryToStorage();
}
}
}

function escapeHtml(text) {
var div = document.createElement('div');
div.appendChild(document.createTextNode(text));
return div.innerHTML;
}

function toggleSidebar(force) {
state.isSidebarOpen = force !== undefined ? force : !state.isSidebarOpen;
if (state.isSidebarOpen) {
dom.sidebar.classList.remove('-translate-x-full');
dom.overlay.classList.remove('pointer-events-none');
dom.overlay.classList.remove('opacity-0');
dom.overlay.classList.add('opacity-100');
} else {
dom.sidebar.classList.add('-translate-x-full');
dom.overlay.classList.add('opacity-0');
dom.overlay.classList.remove('opacity-100');
dom.overlay.classList.add('pointer-events-none');
}
}

function closeAttachmentMenu() {
if (!state.isAttachmentMenuOpen) return;
state.isAttachmentMenuOpen = false;
dom.attachmentMenu.classList.add('opacity-0', 'scale-95', 'translate-y-2', 'pointer-events-none');
dom.attachmentMenu.classList.remove('opacity-100', 'scale-100', 'translate-y-0');
}

function openAttachmentMenu() {
state.isAttachmentMenuOpen = true;
dom.attachmentMenu.classList.remove('opacity-0', 'scale-95', 'translate-y-2', 'pointer-events-none');
dom.attachmentMenu.classList.add('opacity-100', 'scale-100', 'translate-y-0');
}

function toggleAttachmentMenu() {
if (state.isAttachmentMenuOpen) {
closeAttachmentMenu();
} else {
openAttachmentMenu();
}
}

function toggleSearch() {
state.isSearchEnabled = !state.isSearchEnabled;
if (state.isSearchEnabled) {
dom.searchToggleUi.className = 'w-7 h-4 rounded-full relative transition-colors duration-200 bg-[#007AFF]';
dom.searchToggleKnob.classList.add('translate-x-3');
} else {
dom.searchToggleUi.className = 'w-7 h-4 rounded-full relative transition-colors duration-200 bg-white/10';
dom.searchToggleKnob.classList.remove('translate-x-3');
}
closeAttachmentMenu();
}

function addFiles(files, isImage) {
Array.from(files).forEach(function(f) {
var fileObj = {
id: generateId(),
name: f.name,
size: f.size,
type: f.type,
file: f,
isImage: isImage || (f.type && f.type.startsWith('image/'))
};
if (fileObj.isImage && f.type && f.type.startsWith('image/')) {
fileObj.isImage = true;
} else if (isImage) {
fileObj.isImage = true;
} else {
fileObj.isImage = false;
}
state.selectedFiles.push(fileObj);
});
renderFileChips();
updateSendButton();
}

function removeFile(fileId) {
state.selectedFiles = state.selectedFiles.filter(function(f) { return f.id !== fileId; });
renderFileChips();
updateSendButton();
}

function renderFileChips() {
dom.fileChips.innerHTML = '';
state.selectedFiles.forEach(function(fileObj) {
var chip = document.createElement('div');
chip.className = 'flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-white/10 border border-white/5';
var iconSvg;
if (fileObj.isImage) {
iconSvg = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#007AFF" stroke-width="2"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>';
} else {
iconSvg = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#007AFF" stroke-width="2"><path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/></svg>';
}
var sizeStr = '';
if (fileObj.size) {
if (fileObj.size < 1024) {
sizeStr = ' (' + fileObj.size + ' B)';
} else if (fileObj.size < 1024 * 1024) {
sizeStr = ' (' + (fileObj.size / 1024).toFixed(1) + ' KB)';
} else {
sizeStr = ' (' + (fileObj.size / (1024 * 1024)).toFixed(1) + ' MB)';
}
}
var iconSpan = document.createElement('span');
iconSpan.innerHTML = iconSvg;
chip.appendChild(iconSpan);
