removeBtn.className = 'w-4 h-4 flex items-center justify-center rounded-full hover:bg-white/20 text-white/70 hover:text-white transition-colors';
removeBtn.innerHTML = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>';
removeBtn.addEventListener('click', function() { removeFile(fileObj.id); });
chip.appendChild(removeBtn);
dom.fileChips.appendChild(chip);
});
}

function updateSendButton() {
var hasContent = dom.input.value.trim().length > 0 || state.selectedFiles.length > 0;
var canSend = hasContent && !state.isGenerating;
dom.sendBtn.disabled = !canSend;
if (canSend) {
dom.sendBtn.className = 'w-7 h-7 flex items-center justify-center rounded-full shrink-0 mb-0.5 transition-colors bg-[#007AFF] text-white';
} else {
dom.sendBtn.className = 'w-7 h-7 flex items-center justify-center rounded-full shrink-0 mb-0.5 transition-colors bg-[#555555] text-white/50';
}
}

function parseMarkdown(text) {
var segments = [];
var regex = /```([^\n]*)\n([\s\S]*?)```/g;
var lastIndex = 0;
var match;
while ((match = regex.exec(text)) !== null) {
if (match.index > lastIndex) {
var before = text.substring(lastIndex, match.index);
if (before.trim()) {
segments.push({ type: 'text', content: before });
}
}
var lang = match[1].trim() || 'text';
var code = match[2];
segments.push({ type: 'code', lang: lang, code: code });
lastIndex = regex.lastIndex;
}
if (lastIndex < text.length) {
var remaining = text.substring(lastIndex);
if (remaining.trim()) {
segments.push({ type: 'text', content: remaining });
}
}
if (segments.length === 0 && text.trim()) {
segments.push({ type: 'text', content: text });
}
return segments;
}

function shouldAutoScroll() {
var el = dom.messages;
var threshold = 100;
return (el.scrollHeight - el.scrollTop - el.clientHeight) < threshold;
}

function scrollToBottomIfNeeded() {
if (!state.userScrolledUp) {
dom.messages.scrollTop = dom.messages.scrollHeight;
}
}

dom.messages.addEventListener('scroll', function() {
var el = dom.messages;
var atBottom = (el.scrollHeight - el.scrollTop - el.clientHeight) < 100;
state.userScrolledUp = !atBottom;
});

function renderMessages() {
var wasAtBottom = shouldAutoScroll();
dom.messages.innerHTML = '';
state.currentThread.forEach(function(msg) {
var isUser = msg.role === 'user';
var segments = parseMarkdown(msg.content);
var rowDiv = document.createElement('div');
rowDiv.className = 'flex px-4 py-1 ' + (isUser ? 'justify-end' : 'justify-start');
var colDiv = document.createElement('div');
colDiv.className = 'flex flex-col max-w-[85%] md:max-w-[70%] gap-2 ' + (isUser ? 'items-end' : 'items-start');
if (isUser && msg.attachments && msg.attachments.length > 0) {
var attachDiv = document.createElement('div');
attachDiv.className = 'flex flex-wrap gap-1 mb-1';
msg.attachments.forEach(function(att) {
var attChip = document.createElement('span');
attChip.className = 'text-[11px] text-white/70 bg-white/10 px-2 py-0.5 rounded-full';
attChip.textContent = (att.isImage ? '🖼 ' : '📎 ') + att.name;
attachDiv.appendChild(attChip);
});
colDiv.appendChild(attachDiv);
}
segments.forEach(function(seg, idx) {
if (seg.type === 'code') {
var widgetId = msg.id + '-' + idx;
if (!state.codeWidgetStates[widgetId]) {
state.codeWidgetStates[widgetId] = { wrapped: false, copied: false };
}
var s = state.codeWidgetStates[widgetId];
var langLower = seg.lang.toLowerCase();
var color = '#e0e0e0';
if (langLower === 'python') color = '#4B8BBE';
if (langLower === 'javascript' || langLower === 'js') color = '#F7DF1E';
if (langLower === 'html') color = '#E34F26';
if (langLower === 'css') color = '#1572B6';
var wrapperDiv = document.createElement('div');
wrapperDiv.className = 'w-full min-w-[280px]';
var codeContainer = document.createElement('div');
codeContainer.className = 'rounded-lg border border-[#27272a] overflow-hidden my-1.5';
var headerDiv = document.createElement('div');
headerDiv.className = 'flex items-center justify-between px-3 h-8 bg-black border-b border-[#27272a]';
var langSpan = document.createElement('span');
langSpan.className = 'text-[11px] font-mono';
langSpan.style.color = color;
langSpan.textContent = seg.lang.toUpperCase();
headerDiv.appendChild(langSpan);
var btnGroup = document.createElement('div');
btnGroup.className = 'flex gap-1';
var wrapBtn = document.createElement('button');
wrapBtn.className = 'w-[26px] h-[26px] flex items-center justify-center rounded-md border border-white/10 transition-colors ' + (s.wrapped ? 'text-[#007AFF]' : 'text-[#a1a1aa]');
wrapBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="3" x2="21" y1="6" y2="6"/><line x1="3" x2="21" y1="12" y2="12"/><line x1="3" x2="12" y1="18" y2="18"/></svg>';
wrapBtn.addEventListener('click', function() {
s.wrapped = !s.wrapped;
renderMessages();
});
btnGroup.appendChild(wrapBtn);
var copyBtn = document.createElement('button');
copyBtn.className = 'w-[26px] h-[26px] flex items-center justify-center rounded-md border border-white/10 transition-colors ' + (s.copied ? 'text-[#007AFF]' : 'text-[#a1a1aa]');
if (s.copied) {
copyBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6 9 17l-5-5"/></svg>';
} else {
copyBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>';
}
(function(codeText, wId) {
copyBtn.addEventListener('click', function() {
if (navigator.clipboard && navigator.clipboard.writeText) {
navigator.clipboard.writeText(codeText).then(function() {
state.codeWidgetStates[wId].copied = true;
renderMessages();
setTimeout(function() {
state.codeWidgetStates[wId].copied = false;
renderMessages();
}, 2000);
}).catch(function() {
fallbackCopy(codeText, wId);
});
} else {
fallbackCopy(codeText, wId);
}
});
})(seg.code, widgetId);
btnGroup.appendChild(copyBtn);
headerDiv.appendChild(btnGroup);
codeContainer.appendChild(headerDiv);
var codeBody = document.createElement('div');
codeBody.className = 'bg-[#09090b] text-[13px] font-mono p-3 overflow-x-auto ' + (s.wrapped ? 'whitespace-pre-wrap break-words' : 'whitespace-pre') + ' text-[#e4e4e7]';
codeBody.textContent = seg.code;
codeContainer.appendChild(codeBody);
wrapperDiv.appendChild(codeContainer);
colDiv.appendChild(wrapperDiv);
} else if (isUser) {
var userBubble = document.createElement('div');
userBubble.className = 'px-3 py-1.5 rounded-2xl text-white text-[13.5px] leading-relaxed message-user';
userBubble.textContent = seg.content;
colDiv.appendChild(userBubble);
} else {
var assistantDiv = document.createElement('div');
assistantDiv.className = 'text-white text-[13.5px] leading-relaxed prose prose-invert prose-sm max-w-none select-text';
assistantDiv.innerHTML = marked.parse(seg.content);
colDiv.appendChild(assistantDiv);
}
});
rowDiv.appendChild(colDiv);
dom.messages.appendChild(rowDiv);
});
if (state.isGenerating) {
var genDiv = document.createElement('div');
genDiv.className = 'px-4 py-1.5';
var genSpan = document.createElement('span');
genSpan.className = 'text-xs text-[#666]';
genSpan.textContent = 'Generálás...';
genDiv.appendChild(genSpan);
dom.messages.appendChild(genDiv);
}
if (wasAtBottom || !state.userScrolledUp) {
dom.messages.scrollTop = dom.messages.scrollHeight;
state.userScrolledUp = false;
}
}

function fallbackCopy(text, wId) {
var ta = document.createElement('textarea');
ta.value = text;
ta.style.position = 'fixed';
ta.style.left = '-9999px';
document.body.appendChild(ta);
ta.select();
try {
document.execCommand('copy');
state.codeWidgetStates[wId].copied = true;
} catch (e) {
state.codeWidgetStates[wId].copied = false;
}
document.body.removeChild(ta);
renderMessages();
setTimeout(function() {
state.codeWidgetStates[wId].copied = false;
renderMessages();
}, 2000);
}

function renderHistory() {
dom.history.innerHTML = '';
var sorted = state.history.slice().reverse();
sorted.forEach(function(chat) {
var btn = document.createElement('button');
btn.className = 'w-full flex items-center gap-2 px-2.5 py-2 rounded-md hover:bg-white/[0.04] transition-colors';
