def _as_bool(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, bool):
        return v
    s = str(v).strip().lower()
    return s in ("1", "true", "yes", "y", "on", "enabled")


def _clamp_int(v: Any, default: int, min_v: int, max_v: int) -> int:
    try:
        iv = int(v)
    except Exception:
        iv = default
    if iv < min_v:
        return min_v
    if iv > max_v:
        return max_v
    return iv


def _clamp_float(v: Any, default: float, min_v: float, max_v: float) -> float:
    try:
        fv = float(v)
    except Exception:
        fv = default
    if fv < min_v:
        return min_v
    if fv > max_v:
