def _guess_mime(filename: str, declared: Optional[str]) -> str:
    if declared and "/" in declared:
        return declared
    mt, _ = mimetypes.guess_type(filename or "")
    return mt or "application/octet-stream"


def _safe_decode_text(data: bytes) -> str:
    for enc in ("utf-8", "utf-16", "utf-32", "gb18030", "big5", "latin-1"):
        try:
            return data.decode(enc)
        except Exception:
            pass
    return data.decode("utf-8", errors="replace")


