        return ""
    try:
        reader = PdfReader(BytesIO(data))
        parts: List[str] = []
        for p in reader.pages:
            try:
                t = p.extract_text() or ""
            except Exception:
                t = ""
            if t:
                parts.append(t)
            if sum(len(x) for x in parts) >= MAX_EXTRACTED_TEXT_CHARS:
