async def _bigmodel_request(
    client: httpx.AsyncClient,
    api_key: str,
    payload: Dict[str, Any],
) -> Dict[str, Any]:
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    resp = await client.post(BIGMODEL_CHAT_COMPLETIONS_URL, headers=headers, json=payload)
    if resp.status_code >= 400:
        txt = resp.text
        try:
            j = resp.json()
            raise HTTPException(status_code=resp.status_code, detail=j)
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(status_code=resp.status_code, detail=txt)
    try:
        return resp.json()
    except Exception:
        raise HTTPException(status_code=502, detail="Upstream returned invalid JSON")


async def _bigmodel_stream(
    client: httpx.AsyncClient,
    api_key: str,
    payload: Dict[str, Any],
):
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
    }

    async with client.stream("POST", BIGMODEL_CHAT_COMPLETIONS_URL, headers=headers, json=payload) as resp:
        if resp.status_code >= 400:
            b = await resp.aread()
            try:
                j = json.loads(b.decode("utf-8", errors="replace"))
                raise HTTPException(status_code=resp.status_code, detail=j)
            except HTTPException:
                raise
            except Exception:
                raise HTTPException(status_code=resp.status_code, detail=b.decode("utf-8", errors="replace"))

        async for line in resp.aiter_lines():
            if not line:
                continue
            if line.startswith("data:"):
                yield (line + "\n\n").encode("utf-8")
            elif line.startswith(":"):
                yield (line + "\n\n").encode("utf-8")
            else:
                yield (f"data: {line}\n\n").encode("utf-8")


