class SessionManager:
    def __init__(self) -> None:
        self._sessions: Dict[str, SessionData] = {}
        self._lock = threading.RLock()
        self._cleanup_thread = threading.Thread(target=self._cleanup_worker, daemon=True)
        self._cleanup_interval = 3600
        self._session_timeout = 86400
        self._running = True
        self._cleanup_thread.start()

    def create_session(self, system_prompt: str, metadata: Optional[Dict[str, Any]] = None) -> str:
        with self._lock:
            session_id = str(uuid.uuid4())
            new_session = SessionData(
                session_id=session_id,
                system_prompt=system_prompt,
                metadata=metadata or {}
            )
            self._sessions[session_id] = new_session
            return session_id

    def get_session(self, session_id: str) -> Optional[SessionData]:
        with self._lock:
            session = self._sessions.get(session_id)
            if session:
                session.last_active = time.time()
            return session

    def delete_session(self, session_id: str) -> bool:
        with self._lock:
            if session_id in self._sessions:
                del self._sessions[session_id]
                return True
            return False

    def list_sessions(self, limit: int = 100, offset: int = 0) -> List[Dict[str, Any]]:
        with self._lock:
            sorted_sessions = sorted(self._sessions.values(), key=lambda s: s.last_active, reverse=True)
            paginated = sorted_sessions[offset:offset + limit]
            return [
                {
                    "session_id": s.session_id,
                    "message_count": len(s.messages),
                    "created_at": s.created_at,
                    "last_active": s.last_active,
                    "metadata": s.metadata
                }
                for s in paginated
            ]

    def add_message(self, session_id: str, role: str, content: str) -> None:
        session = self.get_session(session_id)
        if not session:
            raise AppError("Session not found", 404)
        with session.lock:
            session.messages.append({"role": role, "content": content})
            session.last_active = time.time()

    def clear_messages(self, session_id: str) -> None:
        session = self.get_session(session_id)
        if not session:
            raise AppError("Session not found", 404)
        with session.lock:
            session.messages.clear()
            session.last_active = time.time()

    def _cleanup_worker(self) -> None:
        while self._running:
            try:
                time.sleep(self._cleanup_interval)
                now = time.time()
                with self._lock:
                    expired_keys = [
                        sid for sid, s in self._sessions.items()
                        if now - s.last_active > self._session_timeout
                    ]
                    for sid in expired_keys:
                        del self._sessions[sid]
                        logger.info(f"Cleaned up expired session: {sid}")
            except Exception as e:
                logger.error(f"Error in session cleanup worker: {e}")

    def shutdown(self) -> None:
        self._running = False
        if self._cleanup_thread.is_alive():
            self._cleanup_thread.join(timeout=2.0)

class RateLimiter:
    def __init__(self, capacity: int, refill_rate: float) -> None:
        self.capacity = capacity
        self.refill_rate = refill_rate
        self.tokens: Dict[str, float] = {}
        self.last_refill: Dict[str, float] = {}
        self.lock = threading.Lock()

    def consume(self, key: str, amount: int = 1) -> bool:
        with self.lock:
            now = time.time()
            if key not in self.tokens:
                self.tokens[key] = float(self.capacity)
                self.last_refill[key] = now
            time_passed = now - self.last_refill[key]
            refill_amount = time_passed * self.refill_rate
            self.tokens[key] = min(float(self.capacity), self.tokens[key] + refill_amount)
            self.last_refill[key] = now
            if self.tokens[key] >= amount:
                self.tokens[key] -= amount
                return True
            return False

class SecurityMiddleware:
    def __init__(self, app: Flask) -> None:
        self.app = app

    def __call__(self, environ: Dict[str, Any], start_response: Callable) -> Any:
        def custom_start_response(status: str, headers: List[Tuple[str, str]], exc_info: Optional[Any] = None) -> Any:
            security_headers = [
                ('X-Content-Type-Options', 'nosniff'),
                ('X-Frame-Options', 'DENY'),
                ('X-XSS-Protection', '1; mode=block'),
                ('Strict-Transport-Security', 'max-age=31536000; includeSubDomains'),
                ('Content-Security-Policy', "default-src 'self'; connect-src *; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'"),
                ('Referrer-Policy', 'strict-origin-when-cross-origin')
            ]
            existing_header_keys = {h[0].lower() for h in headers}
            for key, value in security_headers:
                if key.lower() not in existing_header_keys:
                    headers.append((key, value))
            return start_response(status, headers, exc_info)
        return self.app(environ, custom_start_response)

